"""Symbolic layout compilation for entry harnesses.

The numbering contract follows the toolkit's ``MainBuilder`` convention:
inputs in parameter order, then a non-void result, starting at ``x0``.  Every
visited bool, char, int, enum, string buffer, array or struct reserves one
increasing identifier.  A composite reserves an identifier for itself but
contributes no symbolic object of its own; its children follow in order.
String buffers reserve their identifier and are followed by one character
object per declared byte.  Aliases are transparent and reserve nothing.
"""

from .ast import Alias

SCALAR_WIDTHS = {'bool': 1, 'char': 1, 'enum': 4}


class LayoutError(ValueError):
    """Raised when a type cannot be laid out."""


class Layout(object):
    """The compiled harness layout of one entry module."""

    __slots__ = ('slots', 'count', 'roots', 'result')

    def __init__(self):
        self.slots = []
        self.count = 0
        self.roots = []
        self.result = None

    def expected(self):
        """Map of expected symbolic object name to byte width."""
        objects = {}
        for name, _path, width in self.slots:
            objects[name] = width
        return objects


class LayoutBuilder(object):
    """Reserves symbolic identifiers for a typed harness."""

    def __init__(self):
        self.slots = []
        self.count = 0

    def _reserve(self):
        identifier = self.count
        self.count += 1
        return identifier

    def build(self, type, path):
        """Return the layout node of `type` reached through `path`."""
        while isinstance(type, Alias):
            type = type.target
        identifier = self._reserve()
        kind = type.kind
        if kind == 'bool':
            self.slots.append(('x%d' % identifier, list(path), 1))
            return ('bool', identifier)
        if kind == 'char':
            self.slots.append(('x%d' % identifier, list(path), 1))
            return ('char', identifier)
        if kind == 'int':
            self.slots.append(('x%d' % identifier, list(path), type.width()))
            return ('int', identifier, type.bits)
        if kind == 'enum':
            self.slots.append(('x%d' % identifier, list(path), 4))
            return ('enum', identifier, list(type.values))
        if kind == 'string':
            for position in range(type.maxsize):
                character = self._reserve()
                self.slots.append(('x%d' % character, list(path) + [position], 1))
            return ('string', identifier, type.maxsize)
        if kind == 'array':
            children = [self.build(type.element, list(path) + [position])
                        for position in range(type.size)]
            return ('array', identifier, children)
        if kind == 'struct':
            children = [(name, self.build(field_type, list(path) + [name]))
                        for name, field_type in type.fields]
            return ('struct', identifier, children)
        raise LayoutError('cannot lay out a ' + kind + ' value')


class DeclarationCollector(object):
    """Collects the enum, struct and alias declarations a plan needs.

    Declarations are emitted dependency before user: a post-order walk that
    visits struct fields in order and array and alias children first.
    """

    def __init__(self):
        self.declarations = []
        self.seen = set()

    def collect(self, type):
        """Record every declaration reachable from `type`."""
        if isinstance(type, Alias):
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            self.collect(type.target)
            self.declarations.append(type.name)
            return
        kind = type.kind
        if kind == 'struct':
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            for _name, field_type in type.fields:
                self.collect(field_type)
            self.declarations.append(type.name)
            return
        if kind == 'enum':
            if type.name in self.seen:
                return
            self.seen.add(type.name)
            self.declarations.append(type.name)
            return
        if kind == 'array':
            self.collect(type.element)
            return

    def result(self):
        return list(self.declarations)


def recover(node, values):
    """Rebuild the value of a layout node from recovered object values."""
    kind = node[0]
    if kind == 'bool':
        value = values[node[1]]
        if value != 0 and value != 1:
            raise LeafError('boolean out of range')
        return value == 1
    if kind == 'char':
        return chr(values[node[1]])
    if kind == 'int':
        value = values[node[1]]
        if value >> node[2]:
            raise LeafError('integer padding bits set')
        return value
    if kind == 'enum':
        value = values[node[1]]
        if value >= len(node[2]):
            raise LeafError('enum index out of range')
        return node[2][value]
    if kind == 'string':
        identifier, length = node[1], node[2]
        characters = []
        for position in range(length):
            characters.append(chr(values[identifier + 1 + position]))
        text = ''.join(characters)
        cut = text.find('\x00')
        if cut >= 0:
            return text[:cut]
        return text
    if kind == 'array':
        return [recover(child, values) for child in node[2]]
    if kind == 'struct':
        result = {}
        for name, child in node[2]:
            result[name] = recover(child, values)
        return result
    raise LeafError('unknown layout node')


class LeafError(ValueError):
    """Raised when a recovered leaf value is out of its declared range."""
